function envPositiveInteger(name, fallback) {
  const value = Number(process.env[name]);
  return Number.isInteger(value) && value > 0 ? value : fallback;
}

function sanitizeArtifactLabel(label) {
  return String(label || 'artifact').replace(/[^a-z0-9._-]+/gi, '-').replace(/^-+|-+$/g, '') || 'artifact';
}

function expectedMlsMpmCapacityCounts(base, drop, {
  spareProductSlots = 0
} = {}) {
  const live = base + drop;
  const lineageCapacity = live + spareProductSlots;
  const phaseCompanionSlots = lineageCapacity * 3;
  return {
    base,
    drop,
    live,
    spareProductSlots,
    phaseCompanionSlots,
    total: lineageCapacity + phaseCompanionSlots
  };
}

// Vite dep re-optimization mid-suite 504s dynamic imports; every page gets a
// retrying importer so in-page module loads survive the re-optimize window.
test.beforeEach(async ({ page }) => {
  await page.addInitScript(() => {
    window.__ulgImportWithRetry = async (path) => {
      let lastError = null;
      for (let attempt = 0; attempt < 8; attempt += 1) {
        try {
          return await import(path);
        } catch (error) {
          lastError = error;
          await new Promise((resolve) => setTimeout(resolve, 2500));
        }
      }
      throw lastError;
    };
  });
});

async function ensureSphPhaseOverlayVisible(page, { timeout = 60_000 } = {}) {
  // Two mount families: auto-mount routes never render #run-sph-phase, and
  // button routes may render it late under suite load. Poll for whichever
  // appears first, clicking the button whenever it is present, and let the
  // final toBeVisible be the authoritative gate.
  const overlay = page.locator('#sph-phase-overlay');
  const runButton = page.locator('#run-sph-phase');
  const deadline = Date.now() + timeout;
  const reloadAtMs = Date.now() + Math.min(30_000, timeout / 2);
  let reloaded = false;
  while (await overlay.count() === 0 && Date.now() < deadline) {
    if (await runButton.count() > 0) {
      await runButton.click({ timeout: 2_000 }).catch(() => {});
    } else if (!reloaded && Date.now() > reloadAtMs) {
      // Neither overlay nor button after half the budget usually means the
      // page's own boot imports hit a vite dep re-optimize 504 (which the
      // injected import retrier cannot cover); one reload fetches the
      // settled module graph.
      reloaded = true;
      await page.reload({ waitUntil: 'domcontentloaded' }).catch(() => {});
    }
    await page.waitForTimeout(250);
  }
  await expect(overlay).toBeVisible({ timeout: Math.max(10_000, deadline - Date.now()) });
}

